import csv, json
from collections import defaultdict

# reads
runs = {}
for r in csv.DictReader(open('/app/data/runs.csv')):
    runs[r['run_id']] = r

ref = {}
for r in csv.DictReader(open('/app/data/boards.csv')):
    if r['role']=='reference':
        ref[r['run_id']] = r['tc_id']

series = defaultdict(list)
for r in csv.DictReader(open('/app/data/thermocouples.csv')):
    series[(r['run_id'], r['tc_id'])].append((float(r['t_s']), float(r['temp'])))

ramp_limit = 2.5  # revision B
LIQ = 227.0

report = {'ramp_limit_c_per_s': ramp_limit, 'runs': {}, 'failing_runs': []}
for run in sorted(runs):
    tc = ref.get(run)
    entry = {'tc_id': tc}
    if tc is None or (run,tc) not in series:
        for k in ('max_preheat_ramp','tal_s','peak_c','status'):
            entry[k] = None
        report['runs'][run] = entry
        report['failing_runs'].append(run)
        continue
    pts = sorted(series[(run,tc)])
    unit = runs[run]['temp_unit']
    if unit=='F':
        pts = [(t, (v-32)*5/9) for t,v in pts]
    peak = max(v for _,v in pts)
    # preheat: from start until first sample exceeding 150C, counting only steps where both samples >=50
    ph_steps = []
    for i in range(len(pts)-1):
        t0,v0 = pts[i]; t1,v1 = pts[i+1]
        if v0 >= 50 and v1 >= 50:
            ph_steps.append((t0,v0,t1,v1))
        if v0 > 150:
            break
    max_ramp = 0.0
    for t0,v0,t1,v1 in ph_steps:
        rr = (v1-v0)/(t1-t0)
        max_ramp = max(max_ramp, rr)
    # TAL with linear interpolation
    tal = 0.0
    for i in range(len(pts)-1):
        t0,v0 = pts[i]; t1,v1 = pts[i+1]
        if v0 >= LIQ and v1 >= LIQ:
            tal += t1-t0
        elif v0 < LIQ and v1 >= LIQ:
            frac = (LIQ-v0)/(v1-v0)
            tal += (t1-t0)*frac
        elif v0 >= LIQ and v1 < LIQ:
            frac = (v0-LIQ)/(v0-v1)
            tal += (t1-t0)*frac
    status = 'compliant'
    if not (max_ramp <= ramp_limit and 30 <= tal <= 75 and peak >= 242):
        status = 'non-compliant'
    entry.update({'max_preheat_ramp': round(max_ramp,2), 'tal_s': round(tal,2), 'peak_c': round(peak,2), 'status': status})
    if status=='non-compliant':
        report['failing_runs'].append(run)
    report['runs'][run] = entry

report['failing_runs'] = sorted(report['failing_runs'])
print(json.dumps(report, indent=2))
import os
os.makedirs('/app/output', exist_ok=True)
open('/app/output/reflow_report.json','w').write(json.dumps(report, indent=2))
EOF
