with open('/app/data/sensor_log.csv') as f:
    for row in csv.DictReader(f):
        ts = datetime.strptime(row['timestamp'], '%Y-%m-%d %H:%M')
        if start <= ts < end:
            m = row['machine_id']
            downtime.setdefault(m, 0)

# Need consecutive DOWN runs to exclude micro-stops (<5 min)
# Parse the whole relevant period per machine
import collections
runs = collections.defaultdict(list)
for row in csv.DictReader(open('/app/data/sensor_log.csv')):
    ts = datetime.strptime(row['timestamp'], '%Y-%m-%d %H:%M')
    if start <= ts < end:
        runs[row['machine_id']].append((ts, row['state']))

