            run_len+=1
        else:
            if run_len>=5:
                count+=run_len
            run_len=0
    if run_len>=5:
        count+=run_len
    down_count[m]=count

# ensure all machines present
machines = sorted(set(runs.keys()) | set(down_count.keys()))
res = {m: down_count.get(m,0) for m in machines}
limit=55
over = sorted([m for m in res if res[m]>limit])
out={'limit_min':limit,'downtime_by_machine':{m:res[m] for m in sorted(res)},'over_limit':over}
print(json.dumps(out,indent=2))
json.dump(out, open('/app/output/downtime.json','w'), indent=2)
