# day shift 2026-09-18: 06:00 to 14:00
start = datetime(2026,9,18,6,0)
end = datetime(2026,9,18,14,0)

machines = set()
down_runs = {}  # machine -> list of run lengths (minutes of consecutive DOWN within window)

prev = {}  # machine -> last state within window, plus run counter
runlen = {}

with open('/app/data/sensor_log.csv') as f:
    r = csv.DictReader(f)
    for row in r:
        ts = datetime.strptime(row['timestamp'],'%Y-%m-%d %H:%M')
        m = row['machine_id']
        st = row['state']
        machines.add(m)
        in_win = start <= ts < end
        if in_win:
            if st == 'DOWN':
                runlen[m] = runlen.get(m,0)+1
            else:
                if runlen.get(m,0)>0:
                    down_runs.setdefault(m,[]).append(runlen[m])
                runlen[m]=0
        else:
            if runlen.get(m,0)>0:
                # close run if leaving window while DOWN (shouldn't happen since window contiguous)
                down_runs.setdefault(m,[]).append(runlen[m])
                runlen[m]=0
# flush any open runs
for m in list(runlen):
    if runlen[m]>0:
        down_runs.setdefault(m,[]).append(runlen[m])

result={}
for m in sorted(machines):
    # sum runs of length >= 4 minutes (micro-stops <4 min excluded)
    total = sum(l for l in down_runs.get(m,[]) if l>=4)
    result[m]=total

over=[m for m in sorted(result) if result[m]>45]
