import csv, json

tierA = {'Berlin','Geneva','London','New York','Paris','Tokyo','Zurich'}
tierB = {'Austin','Lisbon','Madrid','Manchester','Osaka'}
caps = {  # category: (A,B)
    'meals': (60,40),
    'lodging': (220,140),
    'taxi': (50,50),
}

emp = {}
for r in csv.DictReader(open('/app/data/employees.csv')):
    emp[r['employee_id']] = r['department']
sales = {k for k,v in emp.items() if v=='Sales'}

claims = list(csv.DictReader(open('/app/data/claims.csv')))
scope = [c for c in claims if c['employee_id'] in sales and '2026-09-01'<=c['date']<='2026-09-30']

violations = []
by_emp = {}
for c in scope:
    eid = c['employee_id']
    cat = c['category']
    city = c['city']
    amt = round(float(c['amount']) * 1.0, 2)  # EUR
    by_emp.setdefault(eid, 0.0)
    reimb = amt
    violation = False
    if cat == 'flights':
        # need pre-approval ID; no cap
        if not c['approval_id'].strip():
            violation = True
            reimb = 0.0
    else:
        # cap
        tier = 'A' if city in tierA else 'B'
        cap = caps[cat][0] if tier=='A' else caps[cat][1]
        # receipt rule
        if amt > 30 and c['receipt'].strip().lower() != 'yes':
            violation = True
            reimb = 0.0
        elif amt > cap:
            violation = True
            reimb = cap
        else:
            reimb = amt
    by_emp[eid] += reimb
    if violation:
        violations.append(c['claim_id'])

violations.sort()
by_emp = {k: round(v,2) for k,v in by_emp.items()}
total = round(sum(by_emp.values()),2)

out = {
  "violations": violations,
  "by_employee": by_emp,
  "reimbursable_eur": total
}
print(json.dumps(out, indent=2))
with open('/app/output/expense_report.json','w') as f:
    json.dump(out,f,indent=2)
